/*
 * A040277  Continued fraction for sqrt(295).
 * https://oeis.org/A040277
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   a(n) = the n-th partial quotient of the continued fraction of
 *            sqrt(295). The sequence is generated by the standard square‑root
 *            continued fraction algorithm. The first term a(0) is
 *            floor(sqrt(295)) = 17. Subsequent terms repeat with a period
 *            that ends when a_k = 2*a0
 * Range:     u8 none, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Forward declaration of types supplied by the build */
typedef uint64_t idx_t; /* assumed definition, not redefined here */

/* Compute the n-th term of A040277 */
seq_t a(idx_t n)
{
    /* constants for sqrt(295) */
    const seq_t a0 = 17u;           /* floor(sqrt(295)) */
    const seq_t D  = 295u;          /* the non‑square integer */

    /* static state to avoid recomputing the period on every call */
    static seq_t *period = NULL;    /* array of period terms (a(1)..a(period_len)) */
    static idx_t period_len = 0;    /* length of the period */
    static int initialized = 0;     /* flag whether period has been built */

    /* helper to build the period once */
    if (!initialized) {
        /* algorithm for continued fractions of sqrt(D) */
        seq_t m = 0;
        seq_t d = 1;
        seq_t a = a0;
        size_t cap = 8;             /* initial allocation size */
        period = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!period) return 0;      /* allocation failure, return 0 as a fallback */

        while (1) {
            /* next values */
            m = d * a - m;
            d = (D - m * m) / d;
            a = (a0 + m) / d;

            /* store a as the next period term */
            if (period_len == cap) {
                cap <<= 1;          /* double the capacity */
                seq_t *tmp = (seq_t *)realloc(period, cap * sizeof(seq_t));
                if (!tmp) { free(period); period = NULL; return 0; }
                period = tmp;
            }
            period[period_len++] = a;

            if (a == a0 * 2) /* end of period */
                break;
        }
        initialized = 1;
    }

    /* answer for n */
    if (n == 0)
        return a0;
    else {
        idx_t idx = (n - 1) % period_len; /* zero‑based index into period array */
        return period[(size_t)idx];
    }
}
